    Q = int(next(it))
    ops = []
    for _ in range(Q):
        t = int(next(it))
        if t == 1:
            v = int(next(it))
            k = int(next(it))
            ops.append((1, v, k))
        else:
            v = int(next(it))
            ops.append((2, v, 0))

    children = [[] for _ in range(N + 1)]
    for i in range(2, N + 1):
        children[p[i]].append(i)

    depth = [0] * (N + 1)
    tin = [0] * (N + 1)
    tout = [0] * (N + 1)
    LOG = 18
    up = [[0] * (N + 1) for _ in range(LOG)]

    for i in range(2, N + 1):
        up[0][i] = p[i]

    timer = 0
    stack = [(1, 0)]
    while stack:
        u, state = stack.pop()
        if state == 0:
            timer += 1
            tin[u] = timer
            stack.append((u, 1))
            for v in reversed(children[u]):
                depth[v] = depth[u] + 1
                stack.append((v, 0))
        else:
            tout[u] = timer

    for j in range(1, LOG):
        up_j = up[j]
        up_jm1 = up[j - 1]
        for i in range(1, N + 1):
            up_j[i] = up_jm1[up_jm1[i]]

    def kth_ancestor(u, k):
        j = 0
        while k:
            if k & 1:
                u = up[j][u]
            k >>= 1
            j += 1
        return u

    size = 4 * N + 5
    tree_val = [0] * size
    tree_time = [0] * size
    cur_time = 0

    def update(node, l, r, ql, qr, val, time):
        if ql <= l and r <= qr:
            tree_val[node] = val
            tree_time[node] = time
            return
        mid = (l + r) // 2
        if ql <= mid:
            update(node * 2, l, mid, ql, qr, val, time)
        if qr > mid:
            update(node * 2 + 1, mid + 1, r, ql, qr, val, time)

    def query(node, l, r, pos, best_val, best_time):
        if tree_time[node] > best_time:
            best_time = tree_time[node]
            best_val = tree_val[node]
        if l == r:
            return best_val
        mid = (l + r) // 2
        if pos <= mid:
            return query(node * 2, l, mid, pos, best_val, best_time)
        else:
            return query(node * 2 + 1, mid + 1, r, pos, best_val, best_time)

    out = []
    for op in ops:
        if op[0] == 1:
            _, u, k = op
            M = query(1, 1, N, tin[u], 0, 0)
            if M == 0:
                ans = kth_ancestor(u, k)
            else:
                if k == 1:
                    ans = M
                else:
                    ans = kth_ancestor(M, k - 1)
            out.append(str(ans))
        else:
            _, v, _ = op
            M = query(1, 1, N, tin[v], 0, 0)
            if M == 0:
                cur_time += 1
                l = tin[v] + 1
                r = tout[v]
                if l <= r:
                    update(1, 1, N, l, r, v, cur_time)

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
